#!/usr/bin/env node

/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

// Parse command-line arguments
const args = process.argv.slice(2);

if (args.length === 0 || !['waves', 'explain', 'pack'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
  process.exit(2);
}

const mode = args[0];

if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
    process.exit(2);
  }
} else if (mode === 'pack') {
  if (args.length !== 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n');
    process.exit(2);
  }
  // Validate worker count
  const workerCountStr = args[1];
  if (!/^\d+$/.test(workerCountStr) || workerCountStr === '0' || workerCountStr[0] === '0' && workerCountStr.length > 1) {
    process.stderr.write('error: workers must be a positive integer\n');
    process.exit(2);
  }
}

// Read stdin
readStdin().then(input => {
  try {
    const graph = parseInput(input);

    // Check for cycles
    const cycle = findCycle(graph);
    if (cycle) {
      process.stderr.write(`error: cycle: ${cycle}\n`);
      process.exit(3);
    }

    if (mode === 'waves') {
      outputWaves(graph);
    } else if (mode === 'explain') {
      outputExplain(graph);
    } else if (mode === 'pack') {
      const workerCount = parseInt(args[1], 10);
      outputPack(graph, workerCount);
    }
  } catch (error) {
    if (error.isParseError) {
      process.stderr.write(error.message + '\n');
      process.exit(2);
    } else {
      throw error;
    }
  }
});

function readStdin() {
  return new Promise((resolve) => {
    let data = '';
    process.stdin.on('data', chunk => {
      data += chunk;
    });
    process.stdin.on('end', () => {
      resolve(data);
    });
  });
}

function parseInput(input) {
  const lines = input.split('\n');
  // Remove empty tail if input ends with newline
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const tasks = new Map(); // name -> cost
  const deps = new Map(); // name -> Set of dependency names
  const undeclaredTasks = new Set();

  let lineNum = 0;

  for (const rawLine of lines) {
    lineNum++;
    const line = rawLine.trim();

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue;
    }

    const parts = line.split(/\s+/);
    const directive = parts[0];

    if (directive === 'task') {
      if (parts.length !== 3) {
        throw createError(`line ${lineNum}: expected task <name> <cost>`);
      }

      const name = parts[1];
      const costStr = parts[2];

      // Validate name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        throw createError(`line ${lineNum}: invalid task name ${name}`);
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        throw createError(`line ${lineNum}: cost must be a non-negative integer`);
      }

      const cost = parseInt(costStr, 10);

      // Check for duplicate task
      if (tasks.has(name)) {
        throw createError(`line ${lineNum}: task ${name} is declared twice`);
      }

      tasks.set(name, cost);
      if (!deps.has(name)) {
        deps.set(name, new Set());
      }
    } else if (directive === 'dep') {
      if (parts.length < 2) {
        throw createError(`line ${lineNum}: expected dep <name> <dependency>...`);
      }

      const name = parts[1];
      const dependencies = parts.slice(2);

      if (!deps.has(name)) {
        deps.set(name, new Set());
      }

      for (const dep of dependencies) {
        deps.get(name).add(dep);
        if (!tasks.has(dep)) {
          undeclaredTasks.add(dep);
        }
      }
    } else {
      throw createError(`line ${lineNum}: unknown directive ${directive}`);
    }
  }

  // Check for unknown tasks first task in input order
  for (const task of undeclaredTasks) {
    throw { message: `error: unknown task ${task}`, isParseError: true };
  }

  return { tasks, deps };
}

function createError(message) {
  return { message: `error: ${message}`, isParseError: true };
}

function findCycle(graph) {
  const { tasks, deps } = graph;
  const visited = new Set();
  const recStack = new Set();
  const path = [];

  const taskNames = Array.from(tasks.keys()).sort();

  for (const startTask of taskNames) {
    visited.clear();
    recStack.clear();
    path.length = 0;

    const result = dfs(startTask, visited, recStack, path, deps, taskNames);
    if (result) {
      return result;
    }
  }

  return null;
}

function dfs(node, visited, recStack, path, deps, allTasks) {
  visited.add(node);
  recStack.add(node);
  path.push(node);

  const nodeDeps = deps.get(node) || new Set();
  const sortedDeps = Array.from(nodeDeps).sort();

  for (const dep of sortedDeps) {
    if (!visited.has(dep)) {
      const result = dfs(dep, visited, recStack, path, deps, allTasks);
      if (result) {
        return result;
      }
    } else if (recStack.has(dep)) {
      // Found a cycle
      const cycleStart = path.indexOf(dep);
      const cycle = path.slice(cycleStart);
      return cycle.join(' -> ') + ' -> ' + cycle[0];
    }
  }

  path.pop();
  recStack.delete(node);
  return null;
}

function computeDepthAndTiming(graph) {
  const { tasks, deps } = graph;
  const depth = new Map(); // task -> wave depth
  const finish = new Map(); // task -> finish time

  const taskNames = Array.from(tasks.keys()).sort();

  // Initialize
  for (const task of taskNames) {
    depth.set(task, -1);
    finish.set(task, -1);
  }

  // Compute depth (topological sort)
  function computeDepth(task, memo = new Map()) {
    if (memo.has(task)) {
      return memo.get(task);
    }

    const taskDeps = deps.get(task) || new Set();
    if (taskDeps.size === 0) {
      memo.set(task, 0);
      return 0;
    }

    let maxDepth = -1;
    for (const dep of taskDeps) {
      const depDepth = computeDepth(dep, memo);
      maxDepth = Math.max(maxDepth, depDepth);
    }

    const d = maxDepth + 1;
    memo.set(task, d);
    return d;
  }

  const depthMemo = new Map();
  for (const task of taskNames) {
    const d = computeDepth(task, depthMemo);
    depth.set(task, d);
  }

  // Compute timing
  const start = new Map();

  function computeTiming(task, memo = new Map()) {
    if (memo.has(task)) {
      return memo.get(task);
    }

    const taskDeps = deps.get(task) || new Set();
    let maxFinish = 0;

    for (const dep of taskDeps) {
      const depFinish = computeTiming(dep, memo);
      maxFinish = Math.max(maxFinish, depFinish);
    }

    const s = maxFinish;
    const f = s + tasks.get(task);

    start.set(task, s);
    memo.set(task, f);
    return f;
  }

  const timingMemo = new Map();
  for (const task of taskNames) {
    computeTiming(task, timingMemo);
    finish.set(task, timingMemo.get(task));
  }

  return { depth, start, finish };
}

function outputWaves(graph) {
  const { tasks, deps } = graph;
  const { depth, finish } = computeDepthAndTiming(graph);

  // Group tasks by depth
  const waves = new Map();
  for (const task of tasks.keys()) {
    const d = depth.get(task);
    if (!waves.has(d)) {
      waves.set(d, []);
    }
    waves.get(d).push(task);
  }

  // Sort each wave's tasks
  for (const d of waves.keys()) {
    waves.get(d).sort();
  }

  // Output waves
  const maxDepth = waves.size > 0 ? Math.max(...waves.keys()) : -1;
  for (let i = 0; i <= maxDepth; i++) {
    const waveTasks = waves.get(i) || [];
    process.stdout.write(`wave ${i}: ${waveTasks.join(' ')}\n`);
  }

  // Compute total makespan
  let maxFinish = 0;
  for (const f of finish.values()) {
    maxFinish = Math.max(maxFinish, f);
  }

  process.stdout.write(`total ${maxFinish}\n`);
}

function outputExplain(graph) {
  const { tasks } = graph;
  const { depth, start, finish } = computeDepthAndTiming(graph);

  const taskNames = Array.from(tasks.keys()).sort();

  for (const task of taskNames) {
    const s = start.get(task);
    const f = finish.get(task);
    const d = depth.get(task);
    process.stdout.write(`${task} start=${s} finish=${f} depth=${d}\n`);
  }

  // Compute total makespan
  let maxFinish = 0;
  for (const f of finish.values()) {
    maxFinish = Math.max(maxFinish, f);
  }

  process.stdout.write(`total ${maxFinish}\n`);
}

function computePriority(task, tasks, deps, memo = new Map()) {
  if (memo.has(task)) {
    return memo.get(task);
  }

  const taskDeps = deps.get(task) || new Set();
  let maxDepChain = 0;

  for (const dep of taskDeps) {
    const depChain = computePriority(dep, tasks, deps, memo);
    maxDepChain = Math.max(maxDepChain, depChain);
  }

  const priority = tasks.get(task) + maxDepChain;
  memo.set(task, priority);
  return priority;
}

function outputPack(graph, workerCount) {
  const { tasks, deps } = graph;

  // Compute priority for each task
  const priority = new Map();
  const priorityMemo = new Map();
  for (const task of tasks.keys()) {
    priority.set(task, computePriority(task, tasks, deps, priorityMemo));
  }

  // Initialize worker state
  const workers = [];
  for (let i = 0; i < workerCount; i++) {
    workers.push({ freeAt: 0, tasks: [] });
  }

  // Initialize task state
  const taskFinish = new Map();
  for (const task of tasks.keys()) {
    taskFinish.set(task, -1);
  }

  // Simulation
  while (true) {
    // Find a task that can be scheduled
    let scheduled = false;

    // Find free worker with minimum index
    let freeWorkerIdx = -1;
    let minFreeTime = Infinity;

    for (let i = 0; i < workerCount; i++) {
      if (workers[i].freeAt < minFreeTime) {
        minFreeTime = workers[i].freeAt;
        freeWorkerIdx = i;
      }
    }

    if (freeWorkerIdx === -1) {
      break;
    }

    const currentTime = workers[freeWorkerIdx].freeAt;

    // Find ready tasks
    const readyTasks = [];
    for (const task of tasks.keys()) {
      if (taskFinish.get(task) === -1) {
        // Check if all dependencies are finished
        const taskDeps = deps.get(task) || new Set();
        let allDepsFinished = true;

        for (const dep of taskDeps) {
          const depFinish = taskFinish.get(dep);
          if (depFinish === -1 || depFinish > currentTime) {
            allDepsFinished = false;
            break;
          }
        }

        if (allDepsFinished) {
          readyTasks.push(task);
        }
      }
    }

    if (readyTasks.length === 0) {
      break;
    }

    // Sort by priority (descending) then by name (ascending)
    readyTasks.sort((a, b) => {
      const prioA = priority.get(a);
      const prioB = priority.get(b);
      if (prioA !== prioB) {
        return prioB - prioA;
      }
      return a.localeCompare(b);
    });

    const task = readyTasks[0];
    const cost = tasks.get(task);
    const startTime = currentTime;
    const finishTime = startTime + cost;

    taskFinish.set(task, finishTime);
    workers[freeWorkerIdx].freeAt = finishTime;
    workers[freeWorkerIdx].tasks.push({ name: task, start: startTime, finish: finishTime });

    scheduled = true;
  }

  // Output
  for (let i = 0; i < workerCount; i++) {
    process.stdout.write(`worker ${i}:`);
    for (const task of workers[i].tasks) {
      process.stdout.write(` ${task.name}@${task.start}-${task.finish}`);
    }
    process.stdout.write('\n');
  }

  // Compute makespan
  let makespan = 0;
  for (const worker of workers) {
    if (worker.tasks.length > 0) {
      const lastTask = worker.tasks[worker.tasks.length - 1];
      makespan = Math.max(makespan, lastTask.finish);
    }
  }

  process.stdout.write(`makespan ${makespan}\n`);
}

