 * Reading a build graph out of the directive text.
 *
 * A graph is `{ names, cost, deps }`: the declared names in ascending order,
 * a name to cost map, and a name to ascending dependency list map.
 */

const NAME = /^[A-Za-z0-9_.-]+$/
const UINT = /^[0-9]+$/

/** A failure that the command reports on standard error and exits 2 for. */
export class InputError extends Error {}

function fail(message) {
  throw new InputError(message)
}

/** Order names by code unit, which is the order the reports are written in. */
export function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

