export function analyse(graph) {
  const { names, cost, deps } = graph
  const { order, dependents } = topological(graph)
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  for (const name of order) {
    let began = 0
    let level = 0
    for (const dep of deps.get(name)) {
      began = Math.max(began, finish.get(dep))
      level = Math.max(level, depth.get(dep) + 1)
    }
    depth.set(name, level)
    start.set(name, began)
    finish.set(name, began + cost.get(name))
  }

