 * Reading a build graph out of the directive text.
 *
 * A graph is `{ names, cost, deps }`: the declared names in ascending order,
 * a name to cost map, and a name to ascending dependency list map.
 */

const NAME = /^[A-Za-z0-9_.-]+$/
const UINT = /^[0-9]+$/

/** A failure that the command reports on standard error and exits 2 for. */
export class InputError extends Error {}

function fail(message) {
  throw new InputError(message)
}

/** Order names by code unit, which is the order the reports are written in. */
export function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const deps = new Map()
  // Every name a dep line mentions, in input order, to report the first
  // undeclared one once the whole input has been read.
  const used = []

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const words = line.split(/\s+/)
    const at = `line ${i + 1}`

    if (words[0] === 'task') {
      if (words.length !== 3) fail(`${at}: expected task <name> <cost>`)
      const [, name, rawCost] = words
      if (!NAME.test(name)) fail(`${at}: invalid task name ${name}`)
      if (!UINT.test(rawCost)) fail(`${at}: cost must be a non-negative integer`)
      if (cost.has(name)) fail(`${at}: task ${name} is declared twice`)
      cost.set(name, Number(rawCost))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (words[0] === 'dep') {
      if (words.length < 3) fail(`${at}: expected dep <name> <dependency>...`)
      for (const name of words.slice(1)) {
        if (!NAME.test(name)) fail(`${at}: invalid task name ${name}`)
        used.push(name)
      }
      const name = words[1]
      let edges = deps.get(name)
      if (!edges) deps.set(name, (edges = new Set()))
      for (const dependency of words.slice(2)) edges.add(dependency)
    } else {
      fail(`${at}: unknown directive ${words[0]}`)
    }
  }

  // A dep line may name a task the input declares later, so the check waits
  // until every task line has been read.
  for (const name of used) {
    if (!cost.has(name)) fail(`unknown task ${name}`)
  }

  const names = [...cost.keys()].sort(byName)
  const sorted = new Map()
  for (const name of names) sorted.set(name, [...deps.get(name)].sort(byName))
  return { names, cost, deps: sorted }
}
