import { byName } from './parse.js'

/**
 * The first cycle a depth first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending
 * order, as the names from the re-entered task back round to itself. The walk
 * is iterative so that a deep graph cannot overflow the stack.
 */
export function findCycle({ names, deps }) {
  const done = new Set()
  const onStack = new Set()

  for (const root of names) {
    if (done.has(root)) continue
    const stack = [{ name: root, next: 0 }]
    onStack.add(root)
    while (stack.length > 0) {
      const frame = stack[stack.length - 1]
      const edges = deps.get(frame.name)
      if (frame.next < edges.length) {
        const dep = edges[frame.next++]
        if (onStack.has(dep)) {
          const from = stack.findIndex((entry) => entry.name === dep)
          const cycle = stack.slice(from).map((entry) => entry.name)
          return [...cycle, cycle[0]]
        }
        if (!done.has(dep)) {
          onStack.add(dep)
          stack.push({ name: dep, next: 0 })
        }
      } else {
        onStack.delete(frame.name)
        done.add(frame.name)
        stack.pop()
      }
    }
  }
  return null
}

/** The dependencies before their dependents; the graph is known acyclic. */
function topological({ names, deps }) {
  const remaining = new Map()
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const name of names) {
    remaining.set(name, deps.get(name).length)
    for (const dep of deps.get(name)) dependents.get(dep).push(name)
  }
  const ready = names.filter((name) => remaining.get(name) === 0)
  const order = []
  for (let i = 0; i < ready.length; i++) {
    const name = ready[i]
    order.push(name)
    for (const dependent of dependents.get(name)) {
      remaining.set(dependent, remaining.get(dependent) - 1)
      if (remaining.get(dependent) === 0) ready.push(dependent)
    }
  }
  return { order, dependents }
}

/**
 * The unlimited worker schedule: each task starts when its last dependency
 * finishes, plus the wave it sits in and the chain cost that drives packing.
 */
export function analyse(graph) {
  const { names, cost, deps } = graph
  const { order, dependents } = topological(graph)
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  for (const name of order) {
    let began = 0
    let level = 0
    for (const dep of deps.get(name)) {
      began = Math.max(began, finish.get(dep))
      level = Math.max(level, depth.get(dep) + 1)
    }
    depth.set(name, level)
    start.set(name, began)
    finish.set(name, began + cost.get(name))
  }

  // A task's priority is the longest chain that begins at it: its own cost
  // plus the best chain through anything that depends on it.
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let below = 0
    for (const dependent of dependents.get(name)) below = Math.max(below, priority.get(dependent))
    priority.set(name, cost.get(name) + below)
  }

  let total = 0
  for (const name of names) total = Math.max(total, finish.get(name))
  return { depth, start, finish, priority, total }
}

export function waves(graph) {
  const { depth, total } = analyse(graph)
  const grouped = []
  for (const name of graph.names) {
    const level = depth.get(name)
    while (grouped.length <= level) grouped.push([])
    grouped[level].push(name)
  }
  const out = grouped.map((group, level) => `wave ${level}: ${group.join(' ')}\n`)
  return out.join('') + `total ${total}\n`
}

export function explain(graph) {
  const { depth, start, finish, total } = analyse(graph)
  let out = ''
  for (const name of graph.names) {
    out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
