export function pack(graph, workerCount) {
  const { cost, deps } = graph
  const { priority } = analyse(graph)

  const free = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const pending = new Set(graph.names)

  let now = 0
  let makespan = 0
  while (pending.size > 0) {
    let started = false
    for (;;) {
      const worker = free.findIndex((at) => at <= now)
      if (worker === -1) break

      let best = null
      for (const name of pending) {
        if (!deps.get(name).every((dep) => finish.has(dep) && finish.get(dep) <= now)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && byName(name, best) < 0)
        ) {
          best = name
        }
      }
      if (best === null) break

      const ends = now + cost.get(best)
      pending.delete(best)
      finish.set(best, ends)
      free[worker] = ends
      runs[worker].push(`${best}@${now}-${ends}`)
      makespan = Math.max(makespan, ends)
      started = true
    }

    if (!started) {
      // Nothing more can begin now, so wait for the next worker to come free.
      let next = Infinity
      for (const at of free) if (at > now) next = Math.min(next, at)
      if (next === Infinity) break
      now = next
    }
  }

  let out = ''
  for (let i = 0; i < workerCount; i++) {
    out += `worker ${i}:${runs[i].map((run) => ' ' + run).join('')}\n`
  }
  return out + `makespan ${makespan}\n`
}
