#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { InputError, parseGraph } from './parse.js'
import { explain, findCycle, pack, waves } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'

function readStdin() {
  return new Promise((resolve, reject) => {
    let text = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      text += chunk
    })
    process.stdin.on('end', () => resolve(text))
    process.stdin.on('error', reject)
  })
}

/** Report on standard error and leave standard output untouched. */
function stop(message, code) {
  process.stderr.write(message + '\n')
  process.exitCode = code
}

function chooseReport(argv) {
  const [mode, ...rest] = argv
  if ((mode === 'waves' || mode === 'explain') && rest.length === 0) {
    return mode === 'waves' ? waves : explain
  }
  if (mode === 'pack' && rest.length === 1) {
    if (!/^[1-9][0-9]*$/.test(rest[0])) {
      throw new InputError('workers must be a positive integer')
    }
    const workers = Number(rest[0])
    return (graph) => pack(graph, workers)
  }
  throw new InputError(USAGE)
}

async function main() {
  let report
  try {
    report = chooseReport(process.argv.slice(2))
  } catch (error) {
    if (!(error instanceof InputError)) throw error
    // The usage line already carries its prefix; the others do not.
    stop(error.message === USAGE ? USAGE : `error: ${error.message}`, 2)
    return
  }

  let graph
  try {
    graph = parseGraph(await readStdin())
  } catch (error) {
    if (!(error instanceof InputError)) throw error
    stop(`error: ${error.message}`, 2)
    return
  }

  const cycle = findCycle(graph)
  if (cycle) {
    stop(`error: cycle: ${cycle.join(' -> ')}`, 3)
    return
  }

  process.stdout.write(report(graph))
}

main()

