 * cost task frees its worker again within the same instant.
 */
export function pack(graph, workerCount) {
  const { cost, deps } = graph
  const { priority } = analyse(graph)

  const free = new Array(workerCount).fill(0)
  const runs = Array.from({ length: workerCount }, () => [])
  const finish = new Map()
  const pending = new Set(graph.names)

  let now = 0
  let makespan = 0
  while (pending.size > 0) {
    let started = false
    for (;;) {
